    Trip t = getTrip();
    int availableSeats = t.getNumberOfSeats() - t.getBookedSeats();
    if (getNumberOfSeats() > availableSeats)
    {
      return false;
    }
    for (Booking otherBooking : getCustomer().getBookings())
    {
      if (otherBooking != this && otherBooking.overlapsWith(t))
      {
        return false;
      }
    }
    LocalDate tripDate = t.getDepartureDate().toInstant().atZone(java.time.ZoneId.systemDefault()).toLocalDate();
    LocalTime tripTime = LocalTime.parse(t.getDepartureTime());
    LocalDateTime departureDateTime = LocalDateTime.of(tripDate, tripTime);
    LocalDate bookDate = getBookingDate().toInstant().atZone(java.time.ZoneId.systemDefault()).toLocalDate();
    LocalTime bookTime = LocalTime.now();
    LocalDateTime bookingDateTime = LocalDateTime.of(bookDate, bookTime);
    long minutesDiff = java.time.Duration.between(bookingDateTime, departureDateTime).toMinutes();
    if (minutesDiff <= 120)
    {
      return false;
    }
